package com.aicharacter.v3;import java.util.*;
public final class Experience {public String experienceId,type,perceivedEvent,locationId,objectId,outcome;public long timestamp;public double novelty,valence,significance;public final List<String> participants=new ArrayList<>(),tags=new ArrayList<>();
 public Experience(String type,String event,double valence,double significance){this.type=type;this.perceivedEvent=event;this.valence=valence;this.significance=significance;this.timestamp=System.currentTimeMillis();this.experienceId="exp_"+timestamp+"_"+Integer.toHexString(Objects.hash(type,event));}
 public Experience id(String id){if(id!=null&&!id.isEmpty())experienceId=id;return this;}public Experience at(String loc,String object){locationId=loc;objectId=object;return this;}public Experience with(String p){participants.add(p);return this;}public Experience tag(String t){tags.add(t);return this;}public Experience outcome(String o){outcome=o;return this;}}
